# qrc_th_common.py: the pieces shared by the hands-on samples (save next to them)
import numpy as np

X = np.array([[0, 1], [1, 0]], dtype=complex)
Z = np.array([[1, 0], [0, -1]], dtype=complex)

def op(single, i, n):
    out = np.array([[1.0 + 0j]])
    for k in range(n):
        out = np.kron(out, single if k == i else np.eye(2))
    return out

def hamiltonian(n, J=1.0, h=1.0, W=0.0, seed=1):
    rng = np.random.default_rng(seed)
    H = np.zeros((2**n, 2**n), dtype=complex)
    for i in range(n):
        for j in range(i + 1, n):
            H += rng.uniform(-J / 2, J / 2) * op(X, i, n) @ op(X, j, n)
    for i in range(n):
        H += (h + rng.uniform(-W / 2, W / 2)) * op(Z, i, n)
    return H

def propagator(H, t):
    E, V = np.linalg.eigh(H)
    return V @ np.diag(np.exp(-1j * E * t)) @ V.conj().T

def inject(rho, s):
    """rho -> |psi(s)><psi(s)| (x) Tr_1 rho with |psi(s)> = sqrt(1-s)|0> + sqrt(s)|1>."""
    D = rho.shape[0]
    r4 = rho.reshape(2, D // 2, 2, D // 2)
    rest = r4[0, :, 0, :] + r4[1, :, 1, :]
    psi = np.array([np.sqrt(1 - s), np.sqrt(s)])
    return np.kron(np.outer(psi, psi), rest)

def run(s, n=4, h=1.0, W=0.0, dt=10.0, V=1, seed=1, rho0=None):
    """Feed inputs s; return features <Z_i> after each of V sub-steps (n*V per input)."""
    D = 2**n
    U = propagator(hamiltonian(n, h=h, W=W, seed=seed), dt / V)
    Zd = [np.real(np.diag(op(Z, i, n))) for i in range(n)]
    rho = np.eye(D) / D if rho0 is None else rho0
    feats = []
    for x in s:
        rho = inject(rho, x)
        f = []
        for _ in range(V):
            rho = U @ rho @ U.conj().T
            d = np.real(np.diag(rho))
            f += [z @ d for z in Zd]
        feats.append(f)
    return np.array(feats), rho

def ridge_fit(F, y, lam=1e-6):
    A = np.hstack([F, np.ones((len(F), 1))])
    return np.linalg.solve(A.T @ A + lam * np.eye(A.shape[1]), A.T @ y)

def ridge_predict(w, F):
    return np.hstack([F, np.ones((len(F), 1))]) @ w

def nmse(pred, y):
    return np.mean((pred - y) ** 2) / np.var(y)
